def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def repeated(seq):
        counts = {}
        for value in seq:
            if value:
                counts[value] = counts.get(value, 0) + 1
        return any(count >= 2 for count in counts.values())

    row_count = sum(repeated(row) for row in grid)
    col_count = sum(repeated([grid[r][c] for r in range(h)]) for c in range(w))
    horizontal = row_count > col_count

    if horizontal:
        lines = [row[:] for row in grid]
    else:
        lines = [[grid[r][c] for r in range(h)] for c in range(w)]

    for line_index, line in enumerate(lines):
        locations = {}
        for i, value in enumerate(line):
            if value:
                locations.setdefault(value, []).append(i)

        for color, positions in locations.items():
            if len(positions) < 2:
                continue

            gaps = [b - a for a, b in zip(positions, positions[1:])]
            step = min(gaps)
            pair_index = gaps.index(step)
            p, q = positions[pair_index], positions[pair_index + 1]

            path = [p, q]
            blocker = None

            i = p
            while i - step >= 0:
                j = i - step
                path.append(j)
                if line[j] != 0 and line[j] != color:
                    blocker = line[j]
                    break
                i = j

            i = q
            while i + step < len(line):
                j = i + step
                path.append(j)
                if line[j] != 0 and line[j] != color:
                    if blocker is None:
                        blocker = line[j]
                    break
                i = j

            draw_color = blocker if blocker is not None else color
            for i in path:
                if horizontal:
                    out[line_index][i] = draw_color
                else:
                    out[i][line_index] = draw_color

    return out
